var generatedRes = []*regexp.Regexp{
	regexp.MustCompile(`(?i)^(?:v|f|u|p|a|r|l|var|arg|args|upv|upval|upvalue|param|slot|reg|loc|local|val|value|index|key|count|tbl|func|fn|num|str|txt|flag|res|ret|tmp|idx|obj|inst|item|list|map|imap|smap|numval|strval|n|k|ok|result)_?\d+$`),
	regexp.MustCompile(`^(?:arg|args|tbl|fn|func|val|tmp|inst|obj|flag|str|txt|num|res|ret|numVal|strVal)$`),
	regexp.MustCompile(`^l_[A-Za-z_][A-Za-z0-9_]*_\d+$`), // l_Players_0 (Medal/Konstant)
	regexp.MustCompile(`^[A-Z]\d+_\d+$`),                 // L0_1 (unluac style)
	regexp.MustCompile(`^(?:[vupal]_)+\d+$`),             // v_u_1 (Medal upvalues)
	regexp.MustCompile(`^_\d+$`),
}

func shouldRenameBinding(b *Binding) bool {
	if !b.Renamable() || b.Name == "_" {
		return false
	}
	if LooksGenerated(b.Name) {
		return true
	}
	if len(b.Name) == 1 {
		switch b.Kind {
		case BindForNum:
			return false
		case BindFor:
			return b.Name != "k" && b.Name != "v" && b.Name != "i"
		default:
			return true
		}
	}
	return false
}

var lNameRe = regexp.MustCompile(`^l_([A-Za-z_][A-Za-z0-9_]*)_\d+$`)

// LooksGenerated reports whether name looks machine-generated by a decompiler.
func LooksGenerated(name string) bool {
	for _, re := range generatedRes {
		if re.MatchString(name) {
			return true
		}
	}
	return false
}

