// SuggestNames infers descriptive names for decompiler-generated variables
// from how they are initialised and used. It never touches names that already
// look human-written. The result maps binding IDs to suggested names.
func (f *File) SuggestNames() map[int]string {
	out := map[int]string{}
	nameOf := func(id int) string {
		if n, ok := out[id]; ok {
			return n
		}
		return f.Bindings[id].Name
	}
	for pass := 0; pass < 4; pass++ {
		changed := false
		for _, b := range f.Bindings {
			if !shouldRenameBinding(b) {
				continue
			}
			if _, already := out[b.ID]; already {
				continue
			}
			var n string
			if m := lNameRe.FindStringSubmatch(b.Name); m != nil {
				n = m[1]
			}
			if n == "" {
				switch b.Kind {
				case BindLocal:
					if b.Body[0] >= 0 {
						n = f.inferFuncBodyNamed(b.Body[0], b.Body[1], nameOf)
					} else if b.Init[0] >= 0 {
						n = f.inferExpr(b.Init[0], b.Init[1], nameOf)
					}
					if n == "" {
						n = f.inferFromRefs(b, nameOf)
					}
				case BindLocalFunc:
					if b.Body[0] >= 0 {
						n = f.inferFuncBodyNamed(b.Body[0], b.Body[1], nameOf)
					}
				case BindParam:
					if ps, ok := eventParams[b.Event]; ok && b.ParamIndex < len(ps) {
						n = ps[b.ParamIndex]
					}
					if n == "" {
						n = f.inferParam(b, nameOf)
					}
				case BindForNum:
					n = "i"
				case BindFor:
					n = f.inferIter(b, nameOf)
				}
			}
			if n != "" && ValidName(n) && n != b.Name {
				out[b.ID] = n
				changed = true
			}
		}
		if !changed {
			break
		}
	}
	return out
}

type segment struct {
	field  string // .Field
	method string // :Method(...)
	arg    string // first string argument of a call, unquoted
	call   bool
}

// chain parses toks[s:e] as a pure suffixed expression (a.b:c("x").d).
// It returns the root token text and the suffix segments, or ok=false when
// the expression is anything else (arithmetic, literals, ...).
func (f *File) chain(s, e int) (root string, rootTok int, segs []segment, ok bool) {
	if s >= e || f.Toks[s].Kind != Name {
		return "", -1, nil, false
	}
	root, rootTok = f.Toks[s].Text, s
	i := s + 1
	for i < e {
		t := f.Toks[i]
		switch {
		case t.Kind == Op && t.Text == "." && i+1 < e && f.Toks[i+1].Kind == Name:
			segs = append(segs, segment{field: f.Toks[i+1].Text})
			i += 2
		case t.Kind == Op && t.Text == ":" && i+1 < e && f.Toks[i+1].Kind == Name:
			seg := segment{method: f.Toks[i+1].Text, call: true}
			j, arg, good := f.skipArgs(i+2, e)
			if !good {
				return "", -1, nil, false
			}
			seg.arg = arg
			segs = append(segs, seg)
			i = j
		case t.Kind == Op && t.Text == "(", t.Kind == String:
			j, arg, good := f.skipArgs(i, e)
			if !good {
				return "", -1, nil, false
			}
			segs = append(segs, segment{call: true, arg: arg})
			i = j
		case t.Kind == Op && t.Text == "[":
			depth := 0
			for ; i < e; i++ {
				if f.Toks[i].Kind == Op && f.Toks[i].Text == "[" {
					depth++
				} else if f.Toks[i].Kind == Op && f.Toks[i].Text == "]" {
					depth--
					if depth == 0 {
						break
					}
				}
			}
			i++
			segs = append(segs, segment{})
		default:
			return "", -1, nil, false
		}
	}
	return root, rootTok, segs, true
}

// skipArgs skips call arguments starting at i and returns the index after
// them plus the first argument when it is a plain string literal.
func (f *File) skipArgs(i, e int) (int, string, bool) {
	if i >= e {
		return i, "", false
	}
	t := f.Toks[i]
	if t.Kind == String {
		return i + 1, unquote(t.Text), true
	}
	if t.Kind != Op || (t.Text != "(" && t.Text != "{") {
		return i, "", false
	}
	open, close := t.Text, ")"
	if open == "{" {
		close = "}"
	}
	arg := ""
	if open == "(" && i+1 < e && f.Toks[i+1].Kind == String {
		arg = unquote(f.Toks[i+1].Text)
	}
	depth := 0
	for ; i < e; i++ {
		tt := f.Toks[i]
		if tt.Kind != Op {
			continue
		}
		switch tt.Text {
		case "(", "{", "[":
			depth++
		case ")", "}", "]":
			depth--
			if depth == 0 && tt.Text == close {
				return i + 1, arg, true
			}
		}
	}
	return i, "", false
}

func unquote(s string) string {
	if len(s) >= 2 && (s[0] == '"' || s[0] == '\'' || s[0] == '`') {
		return s[1 : len(s)-1]
	}
	if strings.HasPrefix(s, "[") {
		if i := strings.Index(s[1:], "["); i >= 0 {
			body := s[i+2:]
			if j := strings.LastIndex(body, "]"); j >= 0 {
				body = body[:j]
				return strings.TrimRight(body, "=]")
			}
		}
	}
	return s
}

func (f *File) inferExpr(s, e int, nameOf func(int) string) string {
	if s >= e {
		return ""
	}
	// Strip outer parentheses or simple fallback `(a and b) or c` for getgenv/gethui
	for s+1 < e && f.Toks[s].Kind == Op && f.Toks[s].Text == "(" && f.matchingClose(s, e) == e-1 {
		s++
		e--
	}
	root, rootTok, segs, ok := f.chain(s, e)
	if !ok {
		return f.inferCompositeExpr(s, e)
	}
	// require(...) -> module name
	if root == "require" && f.Resolve[rootTok] == Global && len(segs) == 1 && segs[0].call {
		return pascal(f.lastNameIn(s+1, e))
	}
	if len(segs) == 0 {
		// Function reference alias `local c = Instance.new` / `local fn = trackConnection` / `local sm = setmetatable`
		if id := f.Resolve[rootTok]; id >= 0 {
			callee := nameOf(id)
			if !LooksGenerated(callee) && len(callee) > 1 {
				return callee
			}
		} else if f.Resolve[rootTok] == Global {
			switch root {
			case "setmetatable", "getmetatable", "tonumber", "tostring", "ipairs", "pairs", "next", "pcall", "xpcall", "select", "unpack", "rawget", "rawset":
				return root + "Fn"
			}
		}
		return ""
	}
	last := segs[len(segs)-1]
	prevName := func() string {
		for i := len(segs) - 2; i >= 0; i-- {
			if segs[i].field != "" {
				return segs[i].field
			}
			if segs[i].method != "" && childFinders[segs[i].method] && segs[i].arg != "" {
				return segs[i].arg
			}
		}
		if f.Resolve[rootTok] >= 0 {
			if n := nameOf(f.Resolve[rootTok]); !LooksGenerated(n) && len(n) > 1 {
				return n
			}
		}
		return ""
	}
	if f.Resolve[rootTok] == Global {
		if len(segs) == 2 && segs[0].field == "new" && segs[1].call && root == "Instance" && last.arg != "" {
			if propName := f.tableNameProp(s+1, e); propName != "" {
				return camel(propName)
			}
			return camel(last.arg)
		}
		if len(segs) == 2 && segs[1].call && segs[0].field != "" {
			if n, ok := constructors[root]; ok {
				return n
			}
			if n, ok := plainCalls[root+"."+segs[0].field]; ok {
				return n
			}
			switch root + "." + segs[0].field {
			case "string.format":
				return "formatted"
			case "string.lower", "string.upper", "string.sub", "string.gsub":
				return "text"
			case "math.clamp", "math.min", "math.max", "math.floor", "math.ceil", "math.round":
				if fld := f.firstFieldInArgs(s+1, e); fld != "" {
					return camel(fld)
				}
			}
		}
		if len(segs) == 1 && !segs[0].call && segs[0].field != "" {
			// Function alias like `local v = Vector3.new` or `local c = Color3.fromRGB`
			if constructors[root] != "" || root == "Instance" || root == "math" || root == "string" || root == "table" {
				return camel(root) + pascal(segs[0].field)
			}
		}
		if len(segs) == 1 && last.call && last.method == "" {
			if n := plainCalls[root]; n != "" {
				return n
			}
			if root == "tostring" {
				if fld := f.firstFieldInArgs(s+1, e); fld != "" {
					return camel(fld) + "Text"
				}
				return "textValue"
			}
			if root == "tonumber" {
				if fld := f.firstFieldInArgs(s+1, e); fld != "" {
					return camel(fld)
				}
				return "numValue"
			}
		}
	}
	// Call to a local/upvalue helper function (`sendHeartbeat()`, `getService("Players")`, `c("Frame", {Name="Switch"})`, `Class.new("Label")`)
	if last.call && last.method == "" {
		callee := ""
		if len(segs) == 1 && f.Resolve[rootTok] >= 0 {
			callee = nameOf(f.Resolve[rootTok])
		} else if len(segs) >= 2 && segs[len(segs)-2].field != "" {
			callee = segs[len(segs)-2].field
			if callee == "new" && len(segs) == 2 && f.Resolve[rootTok] >= 0 {
				if last.arg != "" {
					return camel(last.arg)
				}
				cls := nameOf(f.Resolve[rootTok])
				if !LooksGenerated(cls) && len(cls) > 1 {
					return camel(cls)
				}
			}
		}
		effArg := last.arg
		if effArg == "" && s+2 < e && f.Toks[s+1].Text == "(" && f.Toks[s+2].Kind == Name && f.Resolve[s+2] >= 0 {
			argB := f.Bindings[f.Resolve[s+2]]
			if argB.Init[0] >= 0 && argB.Init[1]-argB.Init[0] == 1 && f.Toks[argB.Init[0]].Kind == String {
				effArg = unquote(f.Toks[argB.Init[0]].Text)
			}
		}
		if n := f.inferFromCallee(callee, effArg, s, e); n != "" {
			return n
		}
		if root == "setmetatable" && f.Resolve[rootTok] == Global {
			// `setmetatable({}, Class)` -> `selfObj` or `camel(Class)`
			for k := s + 2; k < e-1; k++ {
				if f.Toks[k].Text == "," && k+1 < e-1 && f.Toks[k+1].Kind == Name && f.Resolve[k+1] >= 0 {
					cls := nameOf(f.Resolve[k+1])
					if !LooksGenerated(cls) && len(cls) > 1 {
						return camel(cls) + "Obj"
					}
					return "instanceObj"
				}
			}
		}
	}
	switch {
	case last.method == "GetService" && last.arg != "":
		return pascal(last.arg)
	case last.method != "" && childFinders[last.method] && last.arg != "":
		return camel(last.arg)
	case last.method == "Clone":
		if p := prevName(); p != "" {
			return camel(p) + "Clone"
		}
		return "clone"
	case connectMethods[last.method]:
		if p := prevName(); p != "" {
			return camel(p) + "Connection"
		}
		return "connection"
	case last.method == "Wait":
		if p := prevName(); p != "" {
			if ps := eventParams[p]; len(ps) > 0 {
				return ps[0]
			}
			return camel(p) + "Result"
		}
	case last.method == "Create" && len(segs) >= 1:
		if strings.Contains(strings.ToLower(f.Toks[rootTok].Text+prevName()), "tween") {
			return "tween"
		}
	case last.method == "GetAttribute" && last.arg != "":
		return camel(last.arg)
	case last.method == "GetPropertyChangedSignal" && last.arg != "":
		return camel(last.arg) + "Changed"
	case last.method != "":
		return methodNames[last.method]
	case last.field != "":
		if n, ok := fieldNames[last.field]; ok {
			return n
		}
		if len(last.field) >= 2 && !LooksGenerated(last.field) {
			return camel(last.field)
		}
	}
	return ""
}

func (f *File) matchingClose(s, e int) int {
	depth := 0
	for i := s; i < e; i++ {
		if f.Toks[i].Kind == Op {
			switch f.Toks[i].Text {
			case "(", "{", "[":
				depth++
			case ")", "}", "]":
				depth--
				if depth == 0 {
					return i
				}
			}
		}
	}
	return -1
}

func (f *File) inferCompositeExpr(s, e int) string {
	// Single string literal initializer (`.json` / UI class name)
	if e-s == 1 && f.Toks[s].Kind == String {
		str := unquote(f.Toks[s].Text)
		if strings.HasSuffix(str, ".json") || strings.HasSuffix(str, ".txt") || strings.HasSuffix(str, ".cfg") {
			return "fileName"
		}
		if uiClassNames[str] {
			return camel(str) + "Class"
		}
	}
	// Table literal `{__index = ...}` -> `metatable`
	if f.Toks[s].Text == "{" {
		for i := s + 1; i < e && i < s+12; i++ {
			if f.Toks[i].Kind == Name && (f.Toks[i].Text == "__index" || f.Toks[i].Text == "__newindex" || f.Toks[i].Text == "__tostring") {
				return "metatable"
			}
		}
	}
	for i := s; i < e; i++ {
		t := f.Toks[i]
		if t.Kind == Name && f.Resolve[i] == Global {
			switch t.Text {
			case "getgenv":
				return "globalEnv"
			case "gethui":
				return "hiddenGui"
			}
		}
	}
	return ""
}

func (f *File) tableNameProp(s, e int) string {
	for i := s; i+2 < e; i++ {
		if f.Toks[i].Kind == Name && f.Toks[i].Text == "Name" &&
			f.Toks[i+1].Kind == Op && f.Toks[i+1].Text == "=" &&
			f.Toks[i+2].Kind == String {
			v := unquote(f.Toks[i+2].Text)
			if len(v) >= 2 && len(v) <= 28 {
				return v
			}
		}
	}
	return ""
}

func (f *File) firstFieldInArgs(s, e int) string {
	for i := s; i+1 < e; i++ {
		if f.Toks[i].Kind == Op && f.Toks[i].Text == "." && f.Toks[i+1].Kind == Name {
			fld := f.Toks[i+1].Text
			if len(fld) >= 2 && !LooksGenerated(fld) && fld != "new" && fld != "fromRGB" && fld != "fromScale" && fld != "fromOffset" {
				return fld
			}
		}
	}
	return ""
}

var uiClassNames = map[string]bool{
	"ScreenGui": true, "Frame": true, "ScrollingFrame": true, "TextLabel": true, "TextButton": true,
	"TextBox": true, "ImageLabel": true, "ImageButton": true, "ViewportFrame": true, "CanvasGroup": true,
	"UIListLayout": true, "UIGridLayout": true, "UIPadding": true, "UICorner": true, "UIStroke": true,
	"UIGradient": true, "UIAspectRatioConstraint": true, "UISizeConstraint": true, "UIScale": true,
	"Folder": true, "Highlight": true, "BillboardGui": true, "SurfaceGui": true, "Sound": true,
}

func (f *File) inferFromCallee(callee, firstStrArg string, s, e int) string {
	// UI factory pattern: `c("Frame", {Parent = ..., Name = "Switch"})`
	if firstStrArg != "" && uiClassNames[firstStrArg] {
		if prop := f.tableNameProp(s+1, e); prop != "" {
			return camel(prop)
		}
		return camel(firstStrArg)
	}
	if callee == "" || LooksGenerated(callee) {
		return ""
	}
	if callee == "getService" && firstStrArg != "" {
		return pascal(firstStrArg)
	}
	if strings.HasPrefix(callee, "clamp") {
		if fld := f.firstFieldInArgs(s+1, e); fld != "" {
			return camel(fld)
		}
	}
	for _, pfx := range []string{"get", "find", "fetch", "load", "read", "resolve", "compute", "calc", "create", "make", "build", "new"} {
		if strings.HasPrefix(callee, pfx) && len(callee) > len(pfx) && unicode.IsUpper(rune(callee[len(pfx)])) {
			return camel(callee[len(pfx):])
		}
	}
	for _, pfx := range []string{"send", "request", "dispatch"} {
		if strings.HasPrefix(callee, pfx) && len(callee) > len(pfx) && unicode.IsUpper(rune(callee[len(pfx)])) {
			return camel(callee[len(pfx):]) + "Resp"
		}
	}
	for _, pfx := range []string{"parse", "decode"} {
		if strings.HasPrefix(callee, pfx) && len(callee) > len(pfx) && unicode.IsUpper(rune(callee[len(pfx)])) {
			return "parsed" + callee[len(pfx):]
		}
	}
	if strings.HasPrefix(callee, "format") && len(callee) > 6 && unicode.IsUpper(rune(callee[6])) {
		return "formatted" + callee[6:]
	}
	for _, pfx := range []string{"is", "has", "can", "should"} {
		if strings.HasPrefix(callee, pfx) && len(callee) > len(pfx) && unicode.IsUpper(rune(callee[len(pfx)])) {
			return callee
		}
	}
	return ""
}

var safePropParamNames = map[string]string{
	"Parent": "parent", "Name": "name", "Text": "text", "Title": "title",
	"ZIndex": "zIndex", "Color": "color", "TextColor3": "textColor",
	"BackgroundColor3": "bgColor", "BackgroundTransparency": "bgAlpha",
	"Transparency": "transparency", "Thickness": "thickness",
	"Size": "size", "Position": "position", "AnchorPoint": "anchorPoint",
	"Font": "font", "FontFace": "fontFace", "TextSize": "textSize",
	"CornerRadius": "cornerRadius", "Rotation": "rotation",
	"Visible": "visible", "Image": "imageId", "LayoutOrder": "layoutOrder",
	"CFrame": "cframe", "CameraSubject": "cameraSubject",
}

func (f *File) inferParam(b *Binding, nameOf func(int) string) string {
	// Check enclosing function header:
	//  - `xpcall(fn, function(err) ...)` -> `err`
	//  - `Set<Prop> = function([_,] val)` -> `camel(Prop)`
	if b.Decl >= 3 {
		for k := b.Decl - 1; k >= 0 && k >= b.Decl-8; k-- {
			if f.Toks[k].Kind == Keyword && f.Toks[k].Text == "function" {
				if b.ParamIndex == 0 && k >= 4 && f.Toks[k-1].Text == "," && f.Toks[k-3].Text == "(" &&
					f.Toks[k-4].Kind == Name && f.Toks[k-4].Text == "xpcall" {
					return "err"
				}
				if k >= 2 && f.Toks[k-1].Text == "=" && f.Toks[k-2].Kind == Name {
					fnProp := f.Toks[k-2].Text
					// `SetTitle = function(v)` or `SetTitle = function(_, v)`
					isSetterVal := (b.ParamIndex == 0) || (b.ParamIndex == 1 && k+2 < len(f.Toks) && f.Toks[k+2].Text == "_")
					if isSetterVal && strings.HasPrefix(fnProp, "Set") && len(fnProp) > 3 && unicode.IsUpper(rune(fnProp[3])) {
						return camel(fnProp[3:])
					}
				}
				break
			}
		}
	}
	var propCandidate, fieldCandidate, typeCandidate string
	calledDirect := false
	usedStringOps := false
	for _, r := range b.Refs {
		if r == b.Decl {
			continue
		}
		// `typeof(param) == "Instance"` / `type(param) == "table"`
		if r >= 2 && r+4 < len(f.Toks) && f.Toks[r-1].Text == "(" &&
			(f.Toks[r-2].Text == "type" || f.Toks[r-2].Text == "typeof") &&
			f.Toks[r+1].Text == ")" && (f.Toks[r+2].Text == "==" || f.Toks[r+2].Text == "~=") && f.Toks[r+3].Kind == String {
			switch unquote(f.Toks[r+3].Text) {
			case "Instance":
				typeCandidate = "instance"
			case "table":
				typeCandidate = "options"
			case "function":
				typeCandidate = "callback"
			case "string":
				typeCandidate = "text"
			case "number":
				typeCandidate = "num"
			case "boolean":
				typeCandidate = "enabled"
			}
		}
		if r+2 < len(f.Toks) && (f.Toks[r+1].Text == "==" || f.Toks[r+1].Text == "~=") &&
			(f.Toks[r+2].Text == "true" || f.Toks[r+2].Text == "false") && typeCandidate == "" {
			typeCandidate = "enabled"
		}
		// Direct call `param(...)`
		if r+1 < len(f.Toks) && f.Toks[r+1].Kind == Op && f.Toks[r+1].Text == "(" {
			calledDirect = true
		}
		// Method call `param:Method(...)`
		if r+2 < len(f.Toks) && f.Toks[r+1].Kind == Op && f.Toks[r+1].Text == ":" && f.Toks[r+2].Kind == Name {
			m := f.Toks[r+2].Text
			switch m {
			case "Connect", "Once":
				return "signal"
			case "Disconnect":
				return "connection"
			case "Play", "Cancel", "Pause":
				return "tween"
			case "FireServer", "InvokeServer":
				return "remote"
			case "GetService":
				return "gameObj"
			case "FindFirstChild", "WaitForChild", "FindFirstChildOfClass", "FindFirstChildWhichIsA", "GetChildren", "GetDescendants", "IsA", "Destroy":
				fieldCandidate = "instance"
			case "gsub", "match", "gmatch", "sub", "lower", "upper", "find":
				usedStringOps = true
			}
		}
		// Field access `param.Field`
		if r+2 < len(f.Toks) && f.Toks[r+1].Kind == Op && f.Toks[r+1].Text == "." && f.Toks[r+2].Kind == Name {
			fld := f.Toks[r+2].Text
			switch fld {
			case "Character", "UserId", "DisplayName", "Backpack":
				return "player"
			case "Humanoid", "HumanoidRootPart":
				return "character"
			case "CFrame", "AssemblyLinearVelocity", "Velocity":
				if fieldCandidate == "" {
					fieldCandidate = "part"
				}
			case "FontFace", "TextScaled", "TextBounds", "TextColor3":
				if fieldCandidate == "" {
					fieldCandidate = "label"
				}
			case "AbsoluteSize", "AbsolutePosition", "BackgroundTransparency":
				if fieldCandidate == "" {
					fieldCandidate = "frame"
				}
			case "CameraSubject", "ViewportSize":
				return "camera"
			case "Default", "Callback", "Options", "Multi", "Placeholder":
				if fieldCandidate == "" {
					fieldCandidate = "config"
				}
			}
		}
		// Used as table lookup key `tbl[param]` (when inside `__index = function(_, key)`)
		if r >= 2 && r+1 < len(f.Toks) && f.Toks[r-1].Text == "[" && f.Toks[r+1].Text == "]" && fieldCandidate == "" {
			fieldCandidate = "key"
		}
		// First parameter with custom `:Method(...)` call (e.g. `section:Toggle(...)`)
		if b.ParamIndex == 0 && r+2 < len(f.Toks) && f.Toks[r+1].Text == ":" && f.Toks[r+2].Kind == Name && fieldCandidate == "" {
			fieldCandidate = "target"
		}
		// Table property assignment `{..., Prop = param}` or `obj.Prop = param [or default]`
		if r >= 2 && f.Toks[r-1].Kind == Op && f.Toks[r-1].Text == "=" && f.Toks[r-2].Kind == Name &&
			!(r+1 < len(f.Toks) && (f.Toks[r+1].Text == "." || f.Toks[r+1].Text == ":" || f.Toks[r+1].Text == "[")) {
			prop := f.Toks[r-2].Text
			if p, ok := safePropParamNames[prop]; ok && propCandidate == "" {
				propCandidate = p
			} else if r >= 3 && f.Toks[r-3].Text == "." && !LooksGenerated(prop) && len(prop) >= 2 && propCandidate == "" {
				propCandidate = camel(prop)
			}
		}
		// Passed as 1st or 2nd argument to known global/method calls
		if r >= 2 && f.Toks[r-1].Kind == Op && f.Toks[r-1].Text == "(" && f.Toks[r-2].Kind == Name {
			fn := f.Toks[r-2].Text
			switch fn {
			case "GetService":
				return "serviceName"
			case "pcall", "xpcall", "spawn", "defer":
				return "callback"
			case "Connect", "Once":
				return "callback"
			case "readfile", "isfile", "delfile", "loadfile":
				return "filePath"
			case "writefile", "appendfile":
				return "filePath"
			case "isfolder", "makefolder", "delfolder", "listfiles":
				return "folderPath"
			}
		}
		if r >= 4 && f.Toks[r-1].Kind == Op && f.Toks[r-1].Text == "," && f.Toks[r-3].Kind == Op && f.Toks[r-3].Text == "(" && f.Toks[r-4].Kind == Name {
			switch f.Toks[r-4].Text {
			case "writefile", "appendfile":
				return "content"
			}
		}
	}
	if calledDirect {
		return "callback"
	}
	if propCandidate != "" {
		return propCandidate
	}
	if fieldCandidate != "" {
		return fieldCandidate
	}
	if typeCandidate != "" {
		return typeCandidate
	}
	if usedStringOps {
		return "rawText"
	}
	return ""
}

func (f *File) inferFromRefs(b *Binding, nameOf func(int) string) string {
	// `local ok, res = pcall(...)` / `xpcall(...)` -> 1st is `ok`, 2nd is `result`
	if b.Decl >= 1 && b.Decl+3 < len(f.Toks) && f.Toks[b.Decl+1].Text == "," && f.Toks[b.Decl+2].Kind == Name && f.Toks[b.Decl+3].Text == "=" {
		if b.Decl+4 < len(f.Toks) && f.Toks[b.Decl+4].Kind == Name && (f.Toks[b.Decl+4].Text == "pcall" || f.Toks[b.Decl+4].Text == "xpcall") {
			return "ok"
		}
	}
	if b.Decl >= 2 && f.Toks[b.Decl-1].Text == "," && f.Toks[b.Decl-2].Kind == Name {
		first := f.Toks[b.Decl-2].Text
		if id := f.Resolve[b.Decl-2]; id >= 0 {
			first = nameOf(id)
		}
		if first == "ok" || first == "success" {
			for k := b.Decl + 1; k < len(f.Toks) && k <= b.Decl+6; k++ {
				if f.Toks[k].Kind == Name && (f.Toks[k].Text == "pcall" || f.Toks[k].Text == "xpcall") {
					return "result"
				}
			}
		}
	}
	isClassProto := false
	hasJobs := false
	for _, r := range b.Refs {
		if r == b.Decl {
			continue
		}
		// `Class.__index = Class`
		if r+3 < len(f.Toks) && f.Toks[r+1].Text == "." && f.Toks[r+2].Text == "__index" && f.Toks[r+3].Text == "=" {
			isClassProto = true
		}
		if r+2 < len(f.Toks) && f.Toks[r+1].Text == "." && (f.Toks[r+2].Text == "pruneInactive" || f.Toks[r+2].Text == "step") {
			hasJobs = true
		}
		// `game.PlaceId == v` / `game.PlaceId ~= v`
		if r >= 4 && (f.Toks[r-1].Text == "==" || f.Toks[r-1].Text == "~=") && f.Toks[r-2].Text == "PlaceId" {
			return "expectedPlaceId"
		}
		// `x:Disconnect()` -> connection
		if r+2 < len(f.Toks) && f.Toks[r+1].Text == ":" && f.Toks[r+2].Kind == Name {
			switch f.Toks[r+2].Text {
			case "Disconnect":
				return "connection"
			case "Cancel", "Play":
				return "tween"
			}
		}
		// `x.Completed:Connect` -> tween
		if r+2 < len(f.Toks) && f.Toks[r+1].Text == "." && f.Toks[r+2].Text == "Completed" {
			return "tween"
		}
		// `task.wait(x ...)` -> waitSeconds
		if r >= 4 && f.Toks[r-1].Text == "(" && f.Toks[r-2].Text == "wait" && f.Toks[r-3].Text == "." && f.Toks[r-4].Text == "task" {
			return "waitSeconds"
		}
	}
	if isClassProto {
		if hasJobs {
			return "Scheduler"
		}
		return "ClassProto"
	}
	return ""
}

// lastNameIn returns the last string literal or field name inside toks[s:e],
// used to name required modules.
func (f *File) lastNameIn(s, e int) string {
	for i := e - 1; i >= s; i-- {
		t := f.Toks[i]
		if t.Kind == String {
			v := unquote(t.Text)
			if j := strings.LastIndexAny(v, "/."); j >= 0 {
				v = v[j+1:]
			}
			return v
		}
		if t.Kind == Name && i > s && f.Toks[i-1].Kind == Op && f.Toks[i-1].Text == "." {
			return t.Text
		}
	}
	return ""
}

func (f *File) inferIter(b *Binding, nameOf func(int) string) string {
	s, e := b.Iter[0], b.Iter[1]
	if s < 0 {
		return ""
	}
	kind := "" // pairs | ipairs | ""
	cs, ce := s, e
	if f.Toks[s].Kind == Name && (f.Toks[s].Text == "pairs" || f.Toks[s].Text == "ipairs") && f.Resolve[s] == Global &&
		s+1 < e && f.Toks[s+1].Text == "(" && f.Toks[e-1].Text == ")" {
		kind, cs, ce = f.Toks[s].Text, s+2, e-1
	} else if f.Toks[s].Kind == Name && f.Toks[s].Text == "next" && s+1 < e && f.Toks[s+1].Text == "," {
		kind, cs = "pairs", s+2
	}
	container := ""
	arrayLike := kind == "ipairs"
	if root, rootTok, segs, ok := f.chain(cs, ce); ok {
		if len(segs) == 0 {
			if id := f.Resolve[rootTok]; id >= 0 {
				container = nameOf(id)
			} else {
				container = root
			}
		} else if last := segs[len(segs)-1]; last.method != "" {
			container = methodNames[last.method]
			arrayLike = true
		} else if last.field != "" {
			container = last.field
		}
	}
	if b.IterPos == 0 {
		if arrayLike {
			return "index"
		}
		if kind != "" {
			return "key"
		}
		return ""
	}
	if b.IterPos == 1 {
		if container != "" && !LooksGenerated(container) {
			if s := singular(camel(container)); s != "" {
				return s
			}
		}
		if kind != "" || arrayLike {
			return "value"
		}
	}
	return ""
}

func singular(s string) string {
	ls := strings.ToLower(s)
	switch {
	case ls == "children":
		return s[:len(s)-3]
	case strings.HasSuffix(ls, "ies") && len(s) > 4:
		return s[:len(s)-3] + "y"
	case strings.HasSuffix(ls, "ses") || strings.HasSuffix(ls, "xes"):
		return s[:len(s)-2]
	case strings.HasSuffix(ls, "s") && !strings.HasSuffix(ls, "ss") && len(s) > 3:
		return s[:len(s)-1]
	}
	return ""
}

// words splits an arbitrary string ("Remote Events", "kill_brick") into words.
func words(s string) []string {
	return strings.FieldsFunc(s, func(r rune) bool {
		return !(unicode.IsLetter(r) || unicode.IsDigit(r)) || r > unicode.MaxASCII
	})
}

func joinIdent(s string, upperFirst bool) string {
	ws := words(s)
	var sb strings.Builder
	for i, w := range ws {
		w = strings.Trim(w, "_")
		if w == "" {
			continue
		}
		if i == 0 || sb.Len() == 0 {
			if upperFirst {
				w = strings.ToUpper(w[:1]) + w[1:]
			} else if !isAllUpper(w) || len(w) == 1 {
				w = strings.ToLower(w[:1]) + w[1:]
			} else {
				w = strings.ToLower(w)
			}
		} else {
			w = strings.ToUpper(w[:1]) + w[1:]
		}
		sb.WriteString(w)
	}
	out := sb.String()
	if out == "" {
		return ""
	}
	if isDigit(out[0]) {
		out = "_" + out
	}
	return out
}

func isAllUpper(s string) bool {
	for _, r := range s {
		if unicode.IsLower(r) {
			return false
		}
	}
	return true
}

func camel(s string) string  { return joinIdent(s, false) }
func pascal(s string) string { return joinIdent(s, true) }

// ToIdent turns a suggested name into a valid identifier: valid names are
// returned unchanged, anything else ("player gui", "kill-brick") is camelCased.
func ToIdent(s string) string {
	s = strings.TrimSpace(s)
	if identRe.MatchString(s) {
		return s
	}
	return camel(s)
}
